def fhash(paths: list[Path]) -> str:
    h = blake3.blake3()
    for p in paths:
        h.update(f"{p.relative_to(ROOT)}\0".encode())
        h.update((blake3.blake3(p.read_bytes()).hexdigest() if p.exists() else "MISSING").encode() + b"\n")
    return h.hexdigest()


def scripts(s: dict) -> list[str]:
