def statuses(steps: dict[str, dict]) -> dict[str, str]:
    cur, lock, st = hashes(steps), read_lock(), {}
    for u in topo(steps):
        if u not in lock:
            st[u] = "unlocked"
        elif cur[u][0] != lock[u][0]:
            st[u] = "inputs"
        elif cur[u][1] != lock[u][1]:
            st[u] = "rebuilt"
        else:
            st[u] = "ok"
        bad = [d for d in steps[u]["deps"] if st[d] != "ok"]
        if st[u] == "ok" and bad:
            st[u] = "upstream"
    return st


